export type ContactValues = {
  name: string;
  email: string;
  message: string;
};

export type ContactErrors = Partial<Record<keyof ContactValues, string>>;

export type ContactState = {
  values: ContactValues;
  errors: ContactErrors;
  /** Set once a valid message has been sent. */
  success?: string;
};

export const initialContactState: ContactState = {
  values: { name: "", email: "", message: "" },
  errors: {},
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function readContactForm(formData: FormData): ContactValues {
  const field = (name: string) => {
    const value = formData.get(name);
    return typeof value === "string" ? value : "";
  };
  return { name: field("name"), email: field("email"), message: field("message") };
}

/** The rules shared by the server and the browser, applied to trimmed values. */
export function validateContact(values: ContactValues): ContactErrors {
  const name = values.name.trim();
  const email = values.email.trim();
  const message = values.message.trim();
  const errors: ContactErrors = {};

  if (!name) errors.name = "Name is required.";
  if (!email) errors.email = "Email is required.";
  else if (!EMAIL_PATTERN.test(email)) errors.email = "Enter a valid email address.";
  if (message.length < 20) errors.message = "Message must be at least 20 characters.";

  return errors;
}

export function hasErrors(errors: ContactErrors): boolean {
  return Object.keys(errors).length > 0;
}

export function successMessage(name: string): string {
  return `Thanks, ${name.trim()}! Your message has been sent.`;
}
