cat > app/contact/actions.ts <<'EOF'
"use server";

import {
  type ContactState,
  hasErrors,
  readContactForm,
  successMessage,
  validateContact,
} from "@/lib/contact";

export async function sendContact(_prev: ContactState, formData: FormData): Promise<ContactState> {
  const values = readContactForm(formData);
  const errors = validateContact(values);

  if (hasErrors(errors)) {
    return { values, errors };
  }

  // Nothing is stored: a valid message only gets acknowledged.
  return {
    values: { name: "", email: "", message: "" },
    errors: {},
    success: successMessage(values.name),
  };
}
